// ไฟล์นี้สร้างอัตโนมัติด้วย `npm run build:db` — อย่าแก้ด้วยมือ
const SCHEMA = [
 "CREATE TABLE IF NOT EXISTS games (\n  id            TEXT PRIMARY KEY,\n  sort          INTEGER NOT NULL DEFAULT 0,\n  mode          TEXT NOT NULL DEFAULT 'none',\n  name          TEXT NOT NULL,\n  name_en       TEXT DEFAULT '',\n  tagline       TEXT DEFAULT '',\n  duration      INTEGER NOT NULL DEFAULT 10,\n  team_info     TEXT DEFAULT '',\n  goal          TEXT DEFAULT '',\n  rules         TEXT DEFAULT '',\n  steps         TEXT DEFAULT '',\n  tips          TEXT DEFAULT '',\n  win           TEXT DEFAULT '',\n  color         TEXT DEFAULT '#1d4ed8',\n  image         TEXT DEFAULT '',\n  default_image TEXT DEFAULT '',\n  item_label    TEXT DEFAULT 'รายการ',\n  reveal        INTEGER NOT NULL DEFAULT 0,\n  visible       INTEGER NOT NULL DEFAULT 1,\n  updated_at    TEXT DEFAULT CURRENT_TIMESTAMP\n)",
 "CREATE TABLE IF NOT EXISTS items (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  game_id    TEXT NOT NULL,\n  code       TEXT NOT NULL UNIQUE,\n  title      TEXT NOT NULL DEFAULT '',\n  hint       TEXT DEFAULT '',\n  mission    TEXT DEFAULT '',\n  art        TEXT DEFAULT '',\n  image      TEXT DEFAULT '',\n  choices    TEXT DEFAULT '[]',\n  correct    INTEGER DEFAULT -1,\n  category   TEXT DEFAULT '',\n  on_field   INTEGER NOT NULL DEFAULT 1,\n  size       TEXT DEFAULT 'M',\n  answer     TEXT DEFAULT '',\n  sort       INTEGER NOT NULL DEFAULT 0,\n  active     INTEGER NOT NULL DEFAULT 1,\n  updated_at TEXT DEFAULT CURRENT_TIMESTAMP\n)",
 "CREATE INDEX IF NOT EXISTS idx_items_game ON items(game_id, sort)",
 "CREATE TABLE IF NOT EXISTS rooms (\n  id           INTEGER PRIMARY KEY AUTOINCREMENT,\n  code         TEXT NOT NULL UNIQUE,          \n  name         TEXT NOT NULL,\n  status       TEXT NOT NULL DEFAULT 'open',  \n  names_locked INTEGER NOT NULL DEFAULT 0,    \n  created_at   INTEGER NOT NULL\n)",
 "CREATE TABLE IF NOT EXISTS groups (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  room_id    INTEGER NOT NULL,\n  no         INTEGER NOT NULL,\n  name       TEXT NOT NULL,\n  pin        TEXT NOT NULL,                   \n  token      TEXT NOT NULL,                   \n  color      TEXT NOT NULL DEFAULT '#1d4ed8',\n  named      INTEGER NOT NULL DEFAULT 0,      \n  joined_at  INTEGER,\n  created_at INTEGER NOT NULL,\n  UNIQUE (room_id, pin),\n  UNIQUE (room_id, no)\n)",
 "CREATE TABLE IF NOT EXISTS sessions (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  room_id    INTEGER NOT NULL,\n  game_id    TEXT NOT NULL,\n  status     TEXT NOT NULL DEFAULT 'waiting',   \n  started_at INTEGER,\n  ends_at    INTEGER,\n  created_at INTEGER NOT NULL,\n  UNIQUE (room_id, game_id)\n)",
 "CREATE TABLE IF NOT EXISTS answers (\n  id         INTEGER PRIMARY KEY AUTOINCREMENT,\n  session_id INTEGER NOT NULL,\n  group_id   INTEGER NOT NULL,\n  item_id    INTEGER NOT NULL,\n  choice     INTEGER,\n  correct    INTEGER NOT NULL DEFAULT 0,   \n  created_at INTEGER NOT NULL,\n  UNIQUE (session_id, group_id, item_id)\n)",
 "CREATE INDEX IF NOT EXISTS idx_answers_session ON answers(session_id)",
 "CREATE TABLE IF NOT EXISTS results (\n  session_id   INTEGER NOT NULL,\n  group_id     INTEGER NOT NULL,\n  manual       INTEGER NOT NULL DEFAULT 0,\n  submitted_at INTEGER,\n  PRIMARY KEY (session_id, group_id)\n)"
];
