 "INSERT INTO items (game_id, code, title, art, hint, mission, answer, size, sort) VALUES\n('sky-delivery','SK4A9F','พัสดุ #1','💊','ส่งยาให้ร้านขายยา ร้านอยู่ที่ลานสีเดียวกับ \"ผลสตรอว์เบอร์รี\" 🍓','เมื่อไปถึง: เปลี่ยนไฟโดรนเป็น \"สีแดง\" ค้างไว้ 3 วินาที แล้วลงจอด','A (ลานสีแดง)','L',1),\n('sky-delivery','SK7B2D','พัสดุ #2','🍕','ส่งพิซซ่าให้ร้านที่อยู่บนลานสีเดียวกับ \"ท้องฟ้ายามกลางวัน\"','เมื่อไปถึง: ทำท่า Flip 1 ครั้ง แล้วลงจอด','B (ลานสีน้ำเงิน)','M',2),\n('sky-delivery','SK1C8G','พัสดุ #3','📚','ส่งหนังสือให้ห้องสมุด ห้องสมุดอยู่ลานสีเดียวกับ \"ใบไม้\" 🍃','เมื่อไปถึง: บินขึ้นสูงอีก 50 ซม. หมุนตัว 360° แล้วลงจอด','C (ลานสีเขียว)','S',3),\n('sky-delivery','SK6D3K','พัสดุ #4','🎂','ส่งเค้กวันเกิด ร้านเค้กอยู่ลานสีเดียวกับ \"ผลส้ม\" 🍊','เมื่อไปถึง: กะพริบไฟ \"สีเหลือง\" 3 ครั้ง แล้วลงจอด','D (ลานสีส้ม)','S',4)"
